package echo

import (
	"fmt"
	"math/rand"
	"net/http"
	"strings"
	"testing"
)

// reference matcher: returns true if path matches pattern
func zzRefMatch(pattern, path string) bool {
	pp := strings.Split(pattern, "/")
	sp := strings.Split(path, "/")
	i := 0
	for ; i < len(pp); i++ {
		if pp[i] == "*" {
			return true
		}
		if i >= len(sp) {
			return false
		}
		if pp[i] == "" || pp[i][0] == ':' {
			if sp[i] == "" {
				return false
			}
			continue
		}
		if pp[i] != sp[i] {
			return false
		}
	}
	return i == len(sp)
}

func TestZZTmpFuzz(t *testing.T) {
	rnd := rand.New(rand.NewSource(42))
	segPool := []string{"a", "b", "c", ":p", ":q", "*"}
	genPattern := func() string {
		n := rnd.Intn(4) // 0..3 segments
		s := ""
		for i := 0; i < n; i++ {
			s += "/" + segPool[rnd.Intn(len(segPool))]
		}
		if s == "" {
			s = "/"
		}
		return s
	}
	genPath := func() string {
		n := rnd.Intn(5)
		s := ""
		for i := 0; i < n; i++ {
			s += "/" + []string{"a", "b", "c", "x"}[rnd.Intn(4)]
		}
		if s == "" {
			s = "/"
		}
		return s
	}

	panics := 0
	nilHandler := 0
	wrongMatch := 0
	for iter := 0; iter < 20000; iter++ {
		nRoutes := rnd.Intn(4)
		routes := make([]string, 0, nRoutes)
		for i := 0; i < nRoutes; i++ {
			routes = append(routes, genPattern())
		}
		path := genPath()
		method := []string{http.MethodGet, http.MethodPost}[rnd.Intn(2)]

		func() {
			defer func() {
				if rec := recover(); rec != nil {
					panics++
					if panics < 10 {
						t.Errorf("PANIC routes=%v method=%s path=%s: %v", routes, method, path, rec)
					}
				}
			}()
			e := New()
			handlers := map[string]HandlerFunc{}
			for _, r := range routes {
				rr := r
				h := func(c Context) error {
					c.Set("route", rr)
					return nil
				}
				handlers[rr] = h
				e.Add(method, rr, h)
			}
			c := e.NewContext(nil, nil).(*context)
			e.router.Find(method, path, c)
			if c.handler == nil {
				nilHandler++
				if nilHandler < 10 {
					t.Errorf("NIL HANDLER routes=%v method=%s path=%s", routes, method, path)
				}
				return
			}
			_ = c.handler(c)
			got := c.Get("route")
			matched := ""
			for _, r := range routes {
				if zzRefMatch(r, path) {
					matched = r
					break
				}
			}
			if matched == "" {
				if got != nil {
					wrongMatch++
					if wrongMatch < 10 {
						t.Errorf("WRONG MATCH routes=%v method=%s path=%s -> route %v", routes, method, path, got)
					}
				}
			} else if got != matched {
				wrongMatch++
				if wrongMatch < 10 {
					t.Errorf("MATCH MISMATCH routes=%v method=%s path=%s: got %v want %v", routes, method, path, got, matched)
				}
			}
		}()
	}
	fmt.Println("panics:", panics, "nilHandler:", nilHandler, "wrongMatch:", wrongMatch)
}

