		case pattern[i] == '*':
			// any: consumes rest; but requires the preceding static (incl. '/') to have matched
			return true
		default:
			// static: consume pattern chars up to next ':' or '*'
			k := i
			for k < len(pattern) && pattern[k] != ':' && pattern[k] != '*' { k++ }
			lit := pattern[i:k]
			if !strings.HasPrefix(rest, lit) { return false }
			rest = rest[len(lit):]
			i = k
		}
	}
	return rest == ""
}
