	}
	paths := []string{
		"/", "/a", "/ab", "/abc", "/abd", "/a/", "/a/a", "/a/ab", "/a/abc", "/a/b", "/b",
		"/b/a", "/a/b/c", "/a/a/b", "/x", "/x/y", "/a/x/y", "/ab/x", "/a//b", "//a", "/a/x", "/ab/", "/a/ab/c",
	}
	methods := []string{http.MethodGet, http.MethodPost}

	// build route sets: all subsets of size 0..2, plus size 3 for the first 12 patterns
	var sets [][]string
	sets = append(sets, nil)
	for i := range patterns {
		sets = append(sets, []string{patterns[i]})
		for j := i + 1; j < len(patterns); j++ {
			sets = append(sets, []string{patterns[i], patterns[j]})
		}
	}
	for i := 0; i < 12; i++ {
		for j := i + 1; j < 12; j++ {
			for k := j + 1; k < 12; k++ {
				sets = append(sets, []string{patterns[i], patterns[j], patterns[k]})
			}
		}
	}

	bad := 0
	for _, set := range sets {
		// method assignment: all combos for small sets
		nComb := 1
		for range set {
