			for _, path := range paths {
				for _, method := range methods {
					anySame, anyOther := false, false
					for i, p := range set {
						if zzMatch(p, path) {
							if routeMethods[i] == method {
								anySame = true
							} else {
								anyOther = true
							}
						}
					}
					func() {
