							if rec := recover(); rec != nil {
								bad++
								if bad < 15 {
									t.Errorf("PANIC set=%v methods=%v req=%s %s: %v", set, routeMethods, method, path, rec)
								}
							}
						}()
						e := New()
						for i, p := range set {
							pp := p
							e.Add(routeMethods[i], pp, func(c Context) error {
								c.Set("route", pp)
								return nil
							})
						}
						c := e.NewContext(nil, nil).(*context)
						e.router.Find(method, path, c)
						if c.handler == nil {
