									t.Errorf("MATCHED NON-MATCHING ROUTE set=%v methods=%v req=%s %s -> %s", set, routeMethods, method, path, gp)
								}
							}
							if !anySame {
								bad++
								if bad < 15 {
									t.Errorf("MATCHED BUT EXPECTED 404/405 set=%v methods=%v req=%s %s -> %s", set, routeMethods, method, path, gp)
								}
							}
						case err == ErrNotFound:
							if anySame || anyOther {
								bad++
								if bad < 15 {
									t.Errorf("404 BUT ROUTE MATCHES set=%v methods=%v req=%s %s", set, routeMethods, method, path)
								}
							}
						case err == ErrMethodNotAllowed:
							if anySame || !anyOther {
								bad++
								if bad < 15 {
									t.Errorf("405 UNEXPECTED set=%v methods=%v req=%s %s", set, routeMethods, method, path)
								}
							}
						default:
							bad++
							if bad < 15 {
								t.Errorf("UNEXPECTED ERR %v set=%v methods=%v req=%s %s", err, set, routeMethods, method, path)
							}
						}
					}()
				}
			}
		}
	}
	fmt.Println("bad:", bad)
}

