func TestReproGzipEmptyVariants(t *testing.T) {
	// variant 1: handler writes nothing at all
	{
		e := echo.New()
		req := httptest.NewRequest(http.MethodGet, "/", nil)
		req.Header.Set(echo.HeaderAcceptEncoding, gzipScheme)
		rec := httptest.NewRecorder()
		c := e.NewContext(req, rec)
		h := Gzip()(func(c echo.Context) error { return nil })
		if err := h(c); err != nil {
			t.Fatal(err)
		}
		t.Logf("variant1 (no write): bodyLen=%d CE=%q CT=%q", rec.Body.Len(), rec.Header().Get(echo.HeaderContentEncoding), rec.Header().Get(echo.HeaderContentType))
	}
	// variant 2: c.String(200, "")
	{
		e := echo.New()
		req := httptest.NewRequest(http.MethodGet, "/", nil)
		req.Header.Set(echo.HeaderAcceptEncoding, gzipScheme)
		rec := httptest.NewRecorder()
		c := e.NewContext(req, rec)
		h := Gzip()(func(c echo.Context) error { return c.String(http.StatusOK, "") })
		if err := h(c); err != nil {
			t.Fatal(err)
		}
		t.Logf("variant2 (String \"\"): bodyLen=%d CE=%q CT=%q", rec.Body.Len(), rec.Header().Get(echo.HeaderContentEncoding), rec.Header().Get(echo.HeaderContentType))
	}
	// variant 3: explicit Write([]byte{})
	{
		e := echo.New()
		req := httptest.NewRequest(http.MethodGet, "/", nil)
		req.Header.Set(echo.HeaderAcceptEncoding, gzipScheme)
		rec := httptest.NewRecorder()
		c := e.NewContext(req, rec)
		h := Gzip()(func(c echo.Context) error { _, err := c.Response().Write([]byte{}); return err })
		if err := h(c); err != nil {
			t.Fatal(err)
		}
		t.Logf("variant3 (Write empty): bodyLen=%d CE=%q CT=%q", rec.Body.Len(), rec.Header().Get(echo.HeaderContentEncoding), rec.Header().Get(echo.HeaderContentType))
	}
	// variant 4: explicit WriteHeader(200) no body
	{
		e := echo.New()
		req := httptest.NewRequest(http.MethodGet, "/", nil)
		req.Header.Set(echo.HeaderAcceptEncoding, gzipScheme)
		rec := httptest.NewRecorder()
		c := e.NewContext(req, rec)
		h := Gzip()(func(c echo.Context) error { c.Response().WriteHeader(http.StatusOK); return nil })
		if err := h(c); err != nil {
			t.Fatal(err)
		}
		t.Logf("variant4 (WriteHeader 200): bodyLen=%d CE=%q CT=%q", rec.Body.Len(), rec.Header().Get(echo.HeaderContentEncoding), rec.Header().Get(echo.HeaderContentType))
	}
	// variant 5: c.JSON(200, nil)? skip
}

