func TestZZTmpFuzz3(t *testing.T) {
	rnd := rand.New(rand.NewSource(1234))
	patChars := []byte("/ab:*c")
	pathChars := []byte("/abc")
	genPattern := func() string {
		n := 1 + rnd.Intn(7)
		b := []byte("/")
		for i := 0; i < n; i++ {
			b = append(b, patChars[rnd.Intn(len(patChars))])
		}
		return string(b)
	}
	genPath := func() string {
		n := rnd.Intn(8)
		b := []byte("/")
		for i := 0; i < n; i++ {
			b = append(b, pathChars[rnd.Intn(len(pathChars))])
		}
		return string(b)
	}
	panics, nilHandler := 0, 0
	for iter := 0; iter < 300000; iter++ {
		nRoutes := rnd.Intn(4)
		routes := make([]string, 0, nRoutes)
		for i := 0; i < nRoutes; i++ {
			routes = append(routes, genPattern())
		}
		path := genPath()
		method := []string{http.MethodGet, http.MethodPost}[rnd.Intn(2)]
		func() {
			defer func() {
				if rec := recover(); rec != nil {
					panics++
					if panics < 8 {
						t.Errorf("PANIC routes=%v method=%s path=%q: %v", routes, method, path, rec)
					}
				}
			}()
			e := New()
			for _, r := range routes {
				e.Add(method, r, handlerFunc)
			}
			c := e.NewContext(nil, nil).(*context)
			e.router.Find(method, path, c)
			if c.handler == nil {
				nilHandler++
				if nilHandler < 8 {
					t.Errorf("NIL HANDLER routes=%v method=%s path=%q", routes, method, path)
				}
				return
			}
			_ = c.handler(c)
			_ = c.ParamNames()
			_ = c.ParamValues()
			_ = c.Path()
		}()
	}
	fmt.Println("panics:", panics, "nilHandler:", nilHandler)
}

